import warnings,pickle,time
warnings.filterwarnings('ignore')
import numpy as np,pandas as pd
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,HistGradientBoostingRegressor
from sklearn.model_selection import GroupKFold,KFold
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.impute import SimpleImputer
from sklearn.kernel_ridge import KernelRidge
from sklearn.metrics import mean_absolute_error,mean_squared_error
from catboost import CatBoostRegressor

df,structures,X,meta,bt,props=pickle.load(open('/tmp/shg_data.pkl','rb'))
X=X.loc[:,X.iloc[:200].std()>1e-7]
y=df.shg[:200].values
sets={
 'all':X.columns,
 'simple':[c for c in X if not any(c.startswith(p) for p in ['relative_','covalent_'])],
 'chemstruct':[c for c in X if not c.startswith('frac_') and not '_tensor_' in c and not any('_'+e+'_' in c for e in props.index)],
 'tensor':[c for c in X if not c.startswith('frac_') and not any('_'+e+'_' in c for e in props.index)],
}
configs=[]
for fs in ['all','simple','chemstruct','tensor']:
 for depth in [4,6]:
  for trans in ['log']:
   configs.append((f'cb_{fs}_{depth}_{trans}',fs,trans,CatBoostRegressor(iterations=1000,depth=depth,learning_rate=.035,l2_leaf_reg=5,loss_function='RMSE',verbose=False,thread_count=4,random_seed=12)))
for trans in ['sqrt','raw']:
 configs.append((f'cb_all_5_{trans}','all',trans,CatBoostRegressor(iterations=1000,depth=5,learning_rate=.035,l2_leaf_reg=5,loss_function='RMSE',verbose=False,thread_count=4,random_seed=12)))
for fs in ['all','simple','chemstruct','tensor']:
 for trans in ['log','sqrt']:
  configs.append((f'et_{fs}_{trans}',fs,trans,ExtraTreesRegressor(n_estimators=600,min_samples_leaf=2,max_features=.8,n_jobs=4,random_state=12)))
for fs in ['simple','tensor','all']:
 for gamma in [.0003,.001,.003,.01]:
  configs.append((f'krr_{fs}_{gamma}',''+fs,'log',make_pipeline(StandardScaler(),KernelRidge(alpha=.05,kernel='rbf',gamma=gamma))))
results={}
folds=list(GroupKFold(5,shuffle=True,random_state=45).split(X.iloc[:200],y,groups=meta.reduced[:200]))
for name,fs,trans,model in configs:
 start=time.time(); xx=X[sets[fs]].values
 forward={'log':np.log1p,'sqrt':np.sqrt,'raw':lambda x:x}[trans]
 inverse={'log':np.expm1,'sqrt':lambda x:np.maximum(x,0)**2,'raw':lambda x:x}[trans]
 yy=forward(y); oof=np.zeros(200)
 for a,b in folds:
  model.fit(xx[a],yy[a]);oof[b]=inverse(model.predict(xx[b]))
 model.fit(xx[:200],yy);pred=inverse(model.predict(xx[200:]))
 metrics={'mae':mean_absolute_error(y,oof),'logmae':mean_absolute_error(np.log1p(y),np.log1p(np.maximum(oof,0))),'near_mae':mean_absolute_error(y[(y>10)&(y<35)],oof[(y>10)&(y<35)])}
 results[name]={'oof':oof,'pred':pred,**metrics}
 if name.startswith('cb'):
  print('IMPORTANCE',name, sorted(zip(sets[fs],model.feature_importances_),key=lambda q:-q[1])[:18],flush=True)
 print('SCORE',name,metrics,'time',time.time()-start,flush=True)
 print('TOP',[(teid,round(pr,2)) for teid,pr in sorted(zip(df.candidate_id[200:],pred),key=lambda q:abs(q[1]-20))[:12]],flush=True)
 pickle.dump(results,open('/tmp/shg_results.pkl','wb'))
print('DONE')

